import{_ as i,l,o as e,c as s,v as r,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"合并访存","description":"","frontmatter":{"title":"合并访存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-coalescing.md","filePath":"cs/memory-coalescing.md","lastUpdated":1789023840000}'),h={name:"cs/memory-coalescing.md"};function m(_,a,A,B,f,u){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="合并访存" tabindex="-1">合并访存 <a class="header-anchor" href="#合并访存" aria-label="Permalink to &quot;合并访存&quot;">​</a></h1><div class="epigraph"><p>一个 warp 的 32 个 load 若落在同一或少数 cache 行上，硬件合成一两次事务；地址散开则变成几十次，HBM 带宽被事务开销吃掉。</p><footer>—— 据 NVIDIA CUDA 编程指南对 coalescing 的硬件规则；Lindholm et al. 整理</footer></div><p><a href="/cs/warp-divergence">上一课</a> 处理控制不一致。即使掩码全 1，每个线程的指针也可以指向天南海北。<a href="/cs/gpu-memory-hierarchy">GPU 存储</a> 的带宽数字假定突发传输。<a href="/cs/write-combining">CPU 写合并</a> 是窄 store 的近亲。本课缺口是 <strong>coalescing：把一个 warp 的访存收成尽量少的行事务。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>warp 一拍发出 32 个 4B load。若地址构成连续 128B，一次事务即可。若每个线程跳 4KiB，可能 32 次独立事务，延迟无法被占用率完全隐藏，L2 与 HBM 命令总线饱和。缺口不是再切 warp，而是<strong>硬件检测同行/同段，合并请求。</strong></p><p><span class="marginnote">规则随代际变（是否要对齐、是否允许 128B 段上的任意排列）。教学取：空间上落在少数 cache 行内则可合并；完全随机则不能。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内存单元收集该 warp 本拍的地址，按行/扇区分桶，每桶一次事务，数据回填再按线程分发。共享存储则按 bank：同一 bank 不同地址冲突，广播同地址可合并。</p>',8)),(e(),n(p,null,{default:o(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22warp%2032%20load%22%5D%20--%3E%20BKT%5B%22%E6%8C%89%E8%A1%8C%E5%88%86%E6%A1%B6%22%5D%0A%20%20BKT%20--%3E%20FEW%5B%22%E5%90%8C%E8%A1%8C%EF%BC%9A%E5%B0%91%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20BKT%20--%3E%20MANY%5B%22%E6%95%A3%E5%9C%B0%E5%9D%80%EF%BC%9A%E5%A4%9A%E4%BA%8B%E5%8A%A1%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这是 GPU 版空间局部性，粒度是 warp 而不是 CPU 的预取流。SoA 布局常比 AoS 更容易合并。发散与非合并正交：可以控制合流但地址散，或地址齐但路径散。CPU <a href="/cs/stride-stream-prefetch">步长预取</a> 帮单线程流；GPU 更依赖这一拍内的横截面。</p><p>本课不把某框架的 tensor layout 写成作业。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给可运行的测带宽 kernel 作业单。脉动阵列下一课把「合并」变成空间上的邻接传递，不再经过 HBM 事务机。DSA 再下一课。</p><p>后课默认：SIMT 带宽取决于 warp 横截面是否同行。把乘法累加在空间上邻接传递，是脉动阵列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合并把 warp 的访存收成少数行事务；散地址放大事务数。</li><li>共享存储的对应物是 bank 冲突。</li><li>空间邻接的固定数据流是下一课脉动阵列。</li><li>出处：CUDA 硬件合并规则；Lindholm et al.。</li></ul>',8))])}const T=i(h,[["render",m]]);export{C as __pageData,T as default};
